package com.mantou.salesdialer.contacts;
import java.time.Instant;import java.util.Objects;
public final class WorkspaceTimerCheck {
 static int checks;static void eq(Object a,Object b){checks++;if(!Objects.equals(a,b))throw new AssertionError(a+" != "+b);}static void denied(Runnable r,String code){checks++;try{r.run();}catch(Exception e){if(code.equals(e.getMessage()))return;throw new AssertionError(e);}throw new AssertionError("expected "+code);}
 public static void main(String[] args){long now=Instant.parse("2026-10-19T01:00:00Z").toEpochMilli();String token="a".repeat(32);var t=WorkspaceTimerModel.create(3,now+30000,now,1000,"BOOT",token);eq(t.dueElapsed,31000L);eq(t.version,3L);eq(WorkspaceTimerModel.status(t,3,token,now+30000,31000,"BOOT"),"DUE");System.out.println("T641 valid bound single ticket and due callback passed");
 eq(WorkspaceTimerModel.status(t,2,token,now+30000,31000,"BOOT"),"STALE_TIMER");eq(WorkspaceTimerModel.status(t,3,"b".repeat(32),now+30000,31000,"BOOT"),"STALE_TIMER");eq(WorkspaceTimerModel.status(null,3,token,now+30000,31000,"BOOT"),"STALE_TIMER");System.out.println("T642 stale version/token/missing ticket cannot authorize execution passed");
 eq(WorkspaceTimerModel.status(t,3,token,now+29999,30999,"BOOT"),"EARLY_TIMER");eq(WorkspaceTimerModel.status(t,3,token,now+60000,61000,"BOOT"),"DUE");eq(WorkspaceTimerModel.status(t,3,token,now+60001,61001,"BOOT"),"EXPIRED");eq(WorkspaceTimerModel.status(t,3,token,now+30000,61001,"BOOT"),"EXPIRED");System.out.println("T643 inclusive 30 second deadline and no early/late catchup passed");
 eq(WorkspaceTimerModel.status(t,3,token,now+30000,31000,"OTHER"),"TIMER_CLOCK_CHANGED");eq(WorkspaceTimerModel.status(t,3,token,now+35000,31000,"BOOT"),"TIMER_CLOCK_CHANGED");eq(WorkspaceTimerModel.status(t,3,token,now+30000,-1,"BOOT"),"TIMER_CLOCK_CHANGED");System.out.println("T644 boot/monotonic/wall drift guard passed");
 denied(()->WorkspaceTimerModel.create(3,now-1,now,1000,"BOOT",token),"PAST_DUE");denied(()->WorkspaceTimerModel.create(3,now+30000,now,-1,"BOOT",token),"EXECUTION_CLOCK_UNKNOWN");denied(()->WorkspaceTimerModel.create(3,now+30000,now,1000,"",token),"EXECUTION_CLOCK_UNKNOWN");denied(()->WorkspaceTimerModel.create(3,now+30000,now,Long.MAX_VALUE,"BOOT",token),"INVALID_TIMER_TICKET");System.out.println("T645 invalid timing inputs cannot create timer permission passed");
 System.out.println("PASS: "+checks+" assertions; 5 workspace-timer scenarios; no Android or telephone");}
}
